insert into eligibility_rule (id, scheme_id, rule_json, effective_from) select ('10000000-0000-0000-0000-' || lpad(row_number() over (order by id)::text, 12, '0'))::uuid, id, jsonb_build_object('all', jsonb_build_array(jsonb_build_object('field','residentOfIndia','booleanIs',true), jsonb_build_object('field','annualHouseholdIncome','lte',250000))), date '2026-01-01' from scheme;
insert into required_document (id, scheme_id, name, description, requiredness, condition_json, display_order) select ('20000000-0000-0000-0000-' || lpad(row_number() over (order by id)::text, 12, '0'))::uuid, id, 'Demo income declaration', 'Synthetic placeholder document for the prototype; do not collect it.', 'COMMON', null, 1 from scheme;
