insert into application_information (id, scheme_id, application_mode, instructions, application_url, contact_information) select ('40000000-0000-0000-0000-' || lpad(row_number() over (order by id)::text, 12, '0'))::uuid, id, 'INFORMATION_ONLY', 'Demo only: no application can be submitted. Review this synthetic example in the prototype.', null, 'No contact: synthetic demo data.' from scheme;
